import re
data = open(GRAPH_TTL).read()
# ReturnFan_AHU02 and CoolingCoil/HeatingCoil power sensors?
for name in ['ReturnFan_AHU02', 'CoolingCoil_AHU02', 'HeatingCoil_AHU02', 'EconDamper_AHU02', 'ReturnDamper_AHU02']:
    for m in re.finditer(r'bldg:'+name+r'\.?[^\n]*\n(?:\s[^\n]*\n)*?(?=bldg:)', data):
        block = data[m.start():data.find('\n\n\n', m.start())]
        if 'Power_Sensor' in block or 'power' in block.lower():
            print(data[m.start():data.find(' .', m.start())+3 if 'bldg:'+name in data[m.start():m.start()+40] else 0])
    print('=====', name)
# Just find all Electric_Power_Sensor blocks that mention AHU02
for m in re.finditer(r'bldg:\S*_Electric_Power_Sensor[\s\S]*?ref:hasExternalReference <urn:buildgraph:tsref:[^>]*> \.?', data):
    if 'AHU02' in m.group(0)[::50] or True:
        g = m.group(0)
        if 'AHU02' in g:
            print(re.sub(r'\s+',' ',g))
            print('---')
